function ambitoPorInmuebleEscritura(inmuebleId) {
  return esAdminInmuebles() || (activeUser() && inmuebleId is string
    && (pidEnAmbitoEscritura(pidDelInmuebleAmbito(inmuebleId))
      || inmuebleParcialIndexado(pidDelInmuebleAmbito(inmuebleId), inmuebleId, true)));
}
// La relación de alquiler se comprueba contra el inmueble real, no contra
// un propietarioId que puede faltar en documentos históricos o ser antiguo.
// La consulta debe fijar inmuebleId; nunca permite listar toda la colección.
function propietarioLeeAlquiler(d) {
  return isPropietarioRole() && 'inmuebleId' in d && d.inmuebleId is string
    && exists(/databases/$(database)/documents/inmuebles/$(d.inmuebleId))
    && (inmuebleEsMio(get(/databases/$(database)/documents/inmuebles/$(d.inmuebleId)).data)
      || inmuebleAutorizadoExplicito(d.inmuebleId)
      || inmuebleEnCarteraGestionada(get(/databases/$(database)/documents/inmuebles/$(d.inmuebleId)).data)
      || ('propietarioId' in get(/databases/$(database)/documents/inmuebles/$(d.inmuebleId)).data
        && inmuebleParcialIndexado(get(/databases/$(database)/documents/inmuebles/$(d.inmuebleId)).data.propietarioId, d.inmuebleId, false)));
}
// R-2/R-3 — `propietarioId` denormalizado en candidatos y solicitudes_documentacion: sirve para
// listar por titular (`where('propietarioId','==', pid)`). Solo puede valer el titular REAL del
