match /solicitudes/{solicitudId} {
  // BLOQUE E (reconciliado): el inquilino no lee solicitudes (el alta sigue siendo pública).
  // Lectura por cartera (titular o gestor con L del inmueble); listado global solo interno.
  allow get: if isStaff() || ('inmuebleId' in resource.data && ambitoPorInmuebleLectura(resource.data.inmuebleId));
  allow list: if isStaff();
  // P0.2.2 — SIN alta anónima de solicitudes. Solo personal interno o
  // titular/gestor autenticado en su ámbito; el alta pública la escribe el
  // SERVIDOR (`POST /api/solicitud/:token`) con token, honeypot y límite.
  allow create: if isStaff() || (isSignedIn() && 'inmuebleId' in incoming()
    && ambitoPorInmuebleEscritura(incoming().inmuebleId)
    && propietarioCoherenteConInmueble(incoming()));
  // D2 (§7.4): `isSignedIn()` → `isStaff()` (ver candidatos).
  allow update: if isStaff() || ('inmuebleId' in resource.data && ambitoPorInmuebleEscritura(resource.data.inmuebleId));
  allow delete: if isStaff() || ('inmuebleId' in resource.data && ambitoPorInmuebleEscritura(resource.data.inmuebleId));
}

