//  · Anónimo: ninguna operación. El portal público no lee esta colección desde el
//    cliente: lo hace el SERVIDOR con el token de la solicitud
//    (server/ia/portalDocumentacion.ts, cuenta de servicio). Las reglas NO verifican
//    el token: esa verificación es del servidor y de la subida a Storage (ver storage.rules).
//  · `list` (listado global) solo para personal interno. Un titular no lista todas
//    las solicitudes; un listado filtrado por cartera requiere validación en emulador.
//  · Sin `inmuebleId` no hay ámbito: se deniega (fail closed).
//  · `update` no puede reasignar la solicitud a otro inmueble.
// =========================================================================
match /solicitudes_documentacion/{solicitudDocId} {
  allow get: if isStaff() || (
    'inmuebleId' in resource.data && ambitoPorInmuebleLectura(resource.data.inmuebleId)
  );
  // R-3: listado global solo personal; el titular lista SU cartera por `propietarioId` (consulta demostrable).
  allow list: if isStaff() || inmuebleEnCarteraGestionada(resource.data)
    || (isPropietarioRole() && 'propietarioId' in resource.data && resource.data.propietarioId == myPropId());
  allow create: if isStaff() || (
    'inmuebleId' in incoming() && ambitoPorInmuebleEscritura(incoming().inmuebleId)
    && propietarioCoherenteConInmueble(incoming())
  );

